import { api } from './api.js';

export const e = (value = '') => String(value ?? '').replace(/[&<>"']/g, (ch) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const date = (value, options = { month:'short', day:'numeric', year:'numeric' }) => value ? new Date(/^\d{4}-\d\d-\d\d$/.test(String(value))?`${value}T12:00:00`:(value instanceof Date?value.toISOString():value)).toLocaleDateString('en-NG', options) : '—';
const money = (value) => `₦${Number(value || 0).toLocaleString('en-NG',{maximumFractionDigits:2})}`;
const status = (value) => `<span class="badge-soft status-${e(String(value||'pending').toLowerCase())}">${e(String(value||'pending').replaceAll('_',' '))}</span>`;
const empty = (title, copy = 'There is nothing to show yet.') => `<div class="empty-state"><i class="bi bi-inbox"></i><h4>${e(title)}</h4><p>${e(copy)}</p></div>`;
const field = (label, name, type = 'text', value = '', extra = '') => `<div class="${extra.includes('full')?'full':''}"><label class="form-label" for="${e(name)}">${e(label)}</label><input class="form-control" id="${e(name)}" name="${e(name)}" type="${e(type)}" value="${e(value)}" ${extra.replace('full','')}></div>`;
const selectField = (label,name,options,value='',attrs='') => `<div><label class="form-label" for="${e(name)}">${e(label)}</label><select class="form-select" id="${e(name)}" name="${e(name)}" ${attrs}>${options.map(([v,l])=>`<option value="${e(v)}" ${String(value)===String(v)?'selected':''}>${e(l)}</option>`).join('')}</select></div>`;
const sectionHead = (title,sub='',actions='') => `<div class="d-flex justify-content-between align-items-start gap-3 mb-3"><div><h2 class="section-title">${e(title)}</h2>${sub?`<div class="section-subtitle">${e(sub)}</div>`:''}</div>${actions}</div>`;
const panel = (title, content, sub='') => `<section class="panel-card h-100">${sectionHead(title,sub)}${content}</section>`;
const options = (rows, value, label) => rows.map((r)=>[r[value],r[label]]);

export async function renderDashboard(user) {
  const d = await api('/dashboard');
  if (user.role === 'admin') {
    const report = await api('/reports/dashboard');
    return `<div class="welcome-panel mb-4"><div class="welcome-label">ADMINISTRATION · ${e(d.session?.name || 'Academic year')}</div><h2>Good ${new Date().getHours()<12?'morning':new Date().getHours()<17?'afternoon':'evening'}, ${e(user.firstName)}.</h2><p>Here is the latest activity across the Lens Polytechnic portal.</p><div class="mt-3"><a class="btn btn-gold btn-sm" href="#admissions" data-page="admissions">Review applications <i class="bi bi-arrow-right ms-1"></i></a></div></div>
    <div class="row g-3 mb-4">${metric('Active students',d.counts.active_students,'bi-people','blue','Currently matriculated')}${metric('Applications to review',d.counts.pending_applications,'bi-person-lines-fill','gold','Submitted or under review')}${metric('Documents pending',d.counts.pending_documents,'bi-file-earmark-check','green','Awaiting verification')}${metric('Open support tickets',d.counts.open_tickets,'bi-life-preserver','red','Need a response')}</div>
    <div class="row g-3"><div class="col-xl-7"><section class="panel-card">${sectionHead('Applications over time','Monthly applicant accounts created')}<div class="chart-box"><canvas id="applicationChart"></canvas></div></section></div><div class="col-xl-5"><section class="panel-card">${sectionHead('Students by programme','Largest current cohorts')}<div class="chart-box"><canvas id="programmeChart"></canvas></div></section></div>
    <div class="col-12"><section class="panel-card">${sectionHead('Recent applications','Latest applicant activity',`<a class="btn btn-sm btn-outline-primary" href="#admissions" data-page="admissions">View all</a>`)}${d.recent?.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Applicant</th><th>Application no.</th><th>Programme</th><th>Qualification</th><th>Status</th><th>Received</th></tr></thead><tbody>${d.recent.map((r)=>`<tr><td class="fw-semibold">${e(r.first_name)} ${e(r.last_name)}</td><td>${e(r.application_number)}</td><td>${e(r.programme||'—')}</td><td>${e(r.qualification||'—')}</td><td>${status(r.status)}</td><td>${date(r.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No applications yet')}</section></div>
    <div class="col-12">${announcementPanel(d.announcements)}</div></div>`;
  }
  const s=d.student;
  if(!s?.id){
    let application=null; try{application=(await api('/admissions/mine')).application;}catch{}
    return `<div class="welcome-panel mb-4"><div class="welcome-label">APPLICANT PORTAL · ${e(d.session?.name||'Admissions')}</div><h2>Welcome, ${e(user.firstName)}.</h2><p>Continue your Lens Polytechnic admission application and track its progress here.</p><div class="mt-3"><a class="btn btn-gold btn-sm" href="#profile" data-page="profile">Complete your profile <i class="bi bi-arrow-right ms-1"></i></a></div></div><div class="row g-3"><div class="col-lg-7"><section class="panel-card">${sectionHead('Admission application','Your application is reviewed by the Admissions Office')}<div class="d-flex justify-content-between align-items-center p-3 rounded-3 bg-light"><div><div class="metric-label">APPLICATION NUMBER</div><div class="fw-bold mt-1">${e(application?.application_number||'—')}</div></div>${status(application?.status||'draft')}</div><div class="mt-3"><p class="mb-2"><strong>Programme:</strong> ${e(application?.programme||'Choose a programme in your profile')}</p><p class="mb-3"><strong>Academic session:</strong> ${e(application?.academic_session||'—')}</p>${application?.status==='draft'?`<button class="btn btn-primary" data-action="submit-application"><i class="bi bi-send me-2"></i>Submit application for review</button>`:''}</div>${application?.review_notes?`<div class="lock-note mt-3">Admissions note: ${e(application.review_notes)}</div>`:''}</section></div><div class="col-lg-5">${announcementPanel(d.announcements)}</div></div>`;
  }
  const firstName=s.first_name||user.firstName;
  const completion=profileCompletion(s);
  const events=(d.calendar||[]).map((item)=>`<div class="event-item"><div class="event-date">${date(item.starts_at,{month:'short',day:'numeric'})}</div><div><div class="announcement-title">${e(item.title)}</div><div class="announcement-body">${e(item.description||'')}</div></div></div>`).join('');
  const calendarContent=events||empty('No upcoming events');
  const studentSummary=`<section class="panel-card"><div class="d-flex justify-content-between align-items-start gap-3"><div class="student-summary"><img class="student-photo" src="/api/me/photo" alt="Student passport photo" data-hide-error><div><h3>${e([s.first_name,s.middle_name,s.last_name].filter(Boolean).join(' '))}</h3><p>${e(s.programme||'Programme pending')} · ${e(s.qualification||'Applicant')}</p></div></div><a class="btn btn-sm btn-outline-primary" href="#profile" data-page="profile">View profile</a></div><div class="summary-meta"><div>Matriculation number<strong>${e(s.matriculation_number||'Not assigned')}</strong></div><div>Department<strong>${e(s.department||'—')}</strong></div><div>Level<strong>${s.current_level?`${e(s.current_level)}00 Level`:'—'}</strong></div><div>Registration status<strong>${status(s.status||s.admission_status||'pending')}</strong></div></div><div class="d-flex justify-content-between align-items-center mt-4"><div><div class="metric-label">PROFILE COMPLETION</div><div class="progress mt-2" style="height:6px;width:220px"><div class="progress-bar" style="width:${completion}%;background:var(--gold)"></div></div></div><span class="fw-bold small">${completion}%</span></div></section>`;
  return `<div class="welcome-panel mb-4 d-flex justify-content-between align-items-center flex-wrap gap-3"><div><div class="welcome-label">${e(d.session?.name||'Academic session')} · STUDENT PORTAL</div><h2>Welcome back, ${e(firstName)}.</h2><p>Keep an eye on your registration, results and important campus updates.</p></div><div class="welcome-action"><a class="btn btn-gold btn-sm" href="#courses" data-page="courses"><i class="bi bi-journal-check me-1"></i> Course registration</a></div></div>
  <div class="row g-3 mb-4">${metric('Profile completion',`${completion}%`,'bi-person-check','blue','Personal information on file')}${metric('Documents verified',`${d.documents.approved}/${d.documents.total}`,'bi-file-earmark-check','green','Credential review progress')}${metric('Outstanding balance',money(Math.max(0,Number(d.fees.due)-Number(d.fees.paid))),'bi-wallet2','gold','Recorded fee account balance')}${metric('Published CGPA',d.cgpa||'—','bi-bar-chart-line','red','Published results only')}</div>
  <div class="row g-3"><div class="col-xl-7">${studentSummary}<div class="mt-3">${announcementPanel(d.announcements)}</div></div><div class="col-xl-5"><section class="panel-card mb-3">${sectionHead('Academic calendar','Upcoming dates for your current session')}${calendarContent}</section><section class="panel-card">${sectionHead('Quick actions')}<div class="d-grid gap-2"><a class="btn btn-light text-start" href="#documents" data-page="documents"><i class="bi bi-cloud-arrow-up me-2 text-primary"></i>Upload a credential</a><a class="btn btn-light text-start" href="#results" data-page="results"><i class="bi bi-graph-up me-2 text-primary"></i>View academic results</a><a class="btn btn-light text-start" href="#support" data-page="support"><i class="bi bi-life-preserver me-2 text-primary"></i>Get portal support</a></div></section></div></div>`;
}

function metric(label,value,icon,tone,note){return `<div class="col-6 col-xl-3"><div class="metric-card h-100"><div class="metric-top"><span class="metric-label">${e(label)}</span><span class="metric-icon tone-${tone}"><i class="bi ${icon}"></i></span></div><div class="metric-value">${e(value)}</div><div class="metric-note">${e(note)}</div></div></div>`;}
function announcementPanel(rows=[]){return `<section class="panel-card">${sectionHead('Announcements','Notices from Lens Polytechnic')} ${rows?.length?rows.map((a)=>`<div class="announcement-item"><div class="d-flex justify-content-between gap-2"><div class="announcement-title">${e(a.title)}</div><span class="priority priority-${e(a.priority)}">${e(a.priority)}</span></div><div class="announcement-body">${e(a.body)}</div><div class="announcement-meta">${date(a.created_at)}</div></div>`).join(''):empty('No current announcements')}</section>`;}
function profileCompletion(s){const values=[s.first_name,s.last_name,s.email,s.phone,s.date_of_birth,s.gender,s.address,s.state_of_origin,s.guardian_name,s.previous_institution];return Math.round(values.filter(Boolean).length/values.length*100);}

export async function renderProfile(user){
 const {profile:p}=await api('/profile'); const completion=profileCompletion(p);
 const applicantOptions=user.role==='applicant'?await Promise.all([api('/academic/programmes'),api('/academic/sessions')]):null;
 const admissionChoices=user.role==='applicant'&&p.admission_status==='draft'?`<h3 class="form-section-title full">Admission choices</h3><div><label class="form-label" for="programmeId">Programme</label><select class="form-select" name="programmeId" id="programmeId">${applicantOptions[0].programmes.map(x=>`<option value="${x.id}" ${String(p.application_programme_id)===String(x.id)?'selected':''}>${e(x.qualification)} · ${e(x.name)}</option>`).join('')}</select></div><div><label class="form-label" for="academicSessionId">Academic session</label><select class="form-select" name="academicSessionId" id="academicSessionId">${applicantOptions[1].sessions.map(x=>`<option value="${x.id}" ${String(p.application_session_id)===String(x.id)?'selected':''}>${e(x.name)}${x.is_current?' · Current':''}</option>`).join('')}</select></div>`:'';
 return `<div class="row g-3"><div class="col-xl-3"><section class="panel-card text-center"><img class="rounded-circle mx-auto d-block mb-3 profile-photo" src="/api/me/photo" alt="Profile photo" data-fallback-letter="${e((p.first_name||user.firstName||'L')[0])}" style="width:92px;height:92px;object-fit:cover;background:#edf2f7"><h3 class="section-title">${e([p.first_name,p.last_name].filter(Boolean).join(' '))}</h3><div class="section-subtitle">${e(p.matriculation_number||p.application_number||'Applicant')}</div><div class="progress mt-3" style="height:6px"><div class="progress-bar" style="width:${completion}%;background:var(--gold)"></div></div><div class="section-subtitle mt-2">${completion}% profile complete</div><form data-form="photo" class="mt-4"><label class="form-label text-start d-block">Update passport photo</label><input class="form-control form-control-sm" name="photo" type="file" accept="image/jpeg,image/png" required><button class="btn btn-primary btn-sm w-100 mt-2">Upload photo</button></form></section><div class="lock-note mt-3">Academic records and admission decisions are managed by the Academic Office. Contact Student Affairs to request a correction.</div></div><div class="col-xl-9"><form data-form="profile" class="panel-card"><h3 class="form-section-title">Personal information</h3><div class="profile-grid">${field('First name','firstName','text',p.first_name,'required')}${field('Middle name','middleName','text',p.middle_name||'')}${field('Last name','lastName','text',p.last_name,'required')}${field('Email address','email','email',p.email,'disabled')}${field('Phone number','phone','tel',p.phone||'')}${field('Date of birth','dateOfBirth','date',String(p.date_of_birth||'').slice(0,10))}${selectField('Gender','gender',[['','Select gender'],['Female','Female'],['Male','Male'],['Other','Other'],['Prefer not to say','Prefer not to say']],p.gender||'')}${field('State of origin','stateOfOrigin','text',p.state_of_origin||'')}${field('Local government area','localGovernment','text',p.local_government||'')}${field('Marital status','maritalStatus','text',p.marital_status||'')}${field('Nationality','nationality','text',p.nationality||'Nigerian')}${field('Residential address','address','text',p.address||'','full')}
 ${admissionChoices}
 <h3 class="form-section-title full">Parent / guardian and emergency contacts</h3>${field('Parent or guardian name','guardianName','text',p.guardian_name||'')}${field('Parent or guardian phone','guardianPhone','tel',p.guardian_phone||'')}${field('Emergency contact phone','emergencyContact','tel',p.emergency_contact||'')}${field('Previous institution','previousInstitution','text',p.previous_institution||'')}
 <h3 class="form-section-title full">Academic record · managed by the institution</h3><div>${field('Matriculation number','matriculationNumber','text',p.matriculation_number||'','disabled')}</div><div>${field('Programme','programme','text',p.programme?`${p.qualification} · ${p.programme}`:'Application in progress','disabled')}</div><div>${field('Department','department','text',p.department||'—','disabled')}</div><div>${field('Current level','currentLevel','text',p.current_level?`${p.current_level}00 Level`:'—','disabled')}</div><div>${field('Academic session','academicSession','text',p.academic_session||'—','disabled')}</div><div>${field('Admission status','admissionStatus','text',p.admission_status||'—','disabled')}</div></div><div class="d-flex justify-content-end mt-4"><button class="btn btn-primary"><i class="bi bi-check2 me-1"></i>Save profile</button></div></form></div></div>`;
}

export async function renderDocuments(user){
 const {documents}=await api('/documents'); const admin=user.role==='admin';
 const table=documents.length?`<div class="table-wrap"><table class="table"><thead><tr>${admin?'<th>Student</th>':''}<th>Document</th><th>Type</th><th>Uploaded</th><th>Status</th><th>Review note</th><th></th></tr></thead><tbody>${documents.map((d)=>`<tr>${admin?`<td><div class="fw-semibold">${e(d.first_name)} ${e(d.last_name)}</div><div class="text-muted small">${e(d.matriculation_number||d.email)}</div></td>`:''}<td class="fw-semibold">${e(d.title)}<div class="text-muted small">${e(d.original_name)}</div></td><td>${e(d.category.replaceAll('_',' '))}</td><td>${date(d.created_at)}</td><td>${status(d.status)}</td><td>${e(d.verification_comment||'—')}</td><td><button class="btn btn-sm btn-outline-primary" data-action="download" data-id="${d.id}" data-name="${e(d.original_name)}"><i class="bi bi-download"></i></button>${admin?`<button class="btn btn-sm btn-outline-secondary ms-1" data-action="verify-document" data-id="${d.id}" data-status="${e(d.status)}" data-title="${e(d.title)}" data-comment="${e(d.verification_comment||'')}"><i class="bi bi-pencil"></i></button>`:`<button class="btn btn-sm btn-outline-danger ms-1" data-action="delete-document" data-id="${d.id}"><i class="bi bi-trash"></i></button>`}</td></tr>`).join('')}</tbody></table></div>`:empty('No credentials uploaded','Documents will appear here after an upload.');
 return admin?`<section class="panel-card">${sectionHead('Document review','Review student credentials and record an outcome')}<div class="toolbar mb-3"><div class="small text-muted">${documents.length} document${documents.length===1?'':'s'} on record</div><select class="form-select form-select-sm" style="max-width:220px" id="documentFilter"><option value="">All statuses</option>${['pending','under_review','approved','rejected','resubmission_required'].map((x)=>`<option value="${x}">${x.replaceAll('_',' ')}</option>`).join('')}</select></div>${table}</section>`:
 `<div class="row g-3"><div class="col-xl-4"><form data-form="document" class="panel-card"><h3 class="section-title mb-1">Upload a document</h3><p class="section-subtitle mb-3">PDF, JPG or PNG · up to 5 MB</p><div class="mb-3">${selectField('Document category','category',[['waec','WAEC certificate'],['neco','NECO certificate'],['nabteb','NABTEB certificate'],['jamb','JAMB result'],['nd_certificate','National Diploma certificate'],['hnd_certificate','Higher National Diploma certificate'],['statement_of_result','Statement of result'],['transcript','Academic transcript'],['birth_certificate','Birth certificate / age declaration'],['local_government_id','Local government identification'],['admission_letter','Admission letter'],['other','Other supporting document']])}</div><div class="mb-3">${field('Document title','title','text','','required placeholder="e.g. WAEC certificate 2022"')}</div><div class="mb-3"><label class="form-label">Description (optional)</label><textarea class="form-control" name="description" rows="3" placeholder="Add context for the reviewer"></textarea></div><div class="mb-3"><input class="form-control" type="file" name="file" accept=".pdf,.jpg,.jpeg,.png" required></div><button class="btn btn-primary w-100"><i class="bi bi-cloud-arrow-up me-2"></i>Upload for review</button></form></div><div class="col-xl-8"><section class="panel-card">${sectionHead('My documents','Review status and download your uploaded credentials')}${table}</section></div></div>`;
}

export async function renderAdmissions(){
 const {applications}=await api('/admissions');
 return `<section class="panel-card">${sectionHead('Admission applications','Review applications, update decisions and matriculate successful applicants')}<div class="toolbar mb-3"><input class="form-control form-control-sm" id="applicationSearch" placeholder="Search name, application number or email"><span class="chip"><i class="bi bi-person-lines-fill"></i>${applications.length} applications</span></div>${applications.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Applicant</th><th>Application</th><th>Programme</th><th>Session</th><th>Submitted</th><th>Current status</th><th>Review / update</th></tr></thead><tbody>${applications.map((a)=>`<tr data-search-row="${e(`${a.first_name} ${a.last_name} ${a.application_number} ${a.email} ${a.programme}`.toLowerCase())}"><td><div class="fw-semibold">${e(a.first_name)} ${e(a.middle_name||'')} ${e(a.last_name)}</div><div class="text-muted small">${e(a.email)} · ${e(a.phone||'')}</div></td><td>${e(a.application_number)}</td><td>${e(a.qualification||'')} ${e(a.programme||'Programme missing')}</td><td>${e(a.academic_session||'—')}</td><td>${date(a.submitted_at||a.created_at)}</td><td>${status(a.status)}</td><td><form data-form="application-status" class="d-flex gap-2 align-items-center"><input type="hidden" name="id" value="${a.id}"><select class="form-select form-select-sm" name="status" style="min-width:135px">${['submitted','under_review','approved','offered','rejected'].map(x=>`<option value="${x}" ${a.status===x?'selected':''}>${x.replaceAll('_',' ')}</option>`).join('')}</select><button class="btn btn-sm btn-primary" title="Save decision"><i class="bi bi-check2"></i></button><input class="form-control form-control-sm" name="notes" placeholder="Decision note" value="${e(a.review_notes||'')}" style="min-width:150px"></form></td></tr>`).join('')}</tbody></table></div>`:empty('No applications yet')}</section>`;
}

export async function renderStudents(){
 const [{students},{programmes}]=await Promise.all([api('/students'),api('/academic/programmes')]);
 return `<section class="panel-card">${sectionHead('Student directory','Search and manage matriculated student accounts',`<button class="btn btn-primary btn-sm" data-action="add-student"><i class="bi bi-person-plus me-1"></i>Add student</button>`)}<div class="toolbar mb-3"><input class="form-control form-control-sm" id="studentSearch" placeholder="Search name, matriculation number or email"><div class="d-flex gap-2"><button class="btn btn-sm btn-outline-primary" data-action="import-students"><i class="bi bi-upload me-1"></i>Import CSV</button><button class="btn btn-sm btn-outline-secondary" data-action="export-students"><i class="bi bi-download me-1"></i>Export</button></div></div>${students.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Matriculation no.</th><th>Programme</th><th>Department</th><th>Level</th><th>Status</th><th>Manage</th></tr></thead><tbody>${students.map(s=>`<tr data-search-row="${e(`${s.first_name} ${s.last_name} ${s.matriculation_number} ${s.email}`.toLowerCase())}"><td><div class="fw-semibold">${e(s.first_name)} ${e(s.middle_name||'')} ${e(s.last_name)}</div><div class="text-muted small">${e(s.email)}</div></td><td>${e(s.matriculation_number)}</td><td>${e(s.programme)} <span class="text-muted">${e(s.qualification)}</span></td><td>${e(s.department)}</td><td>${e(s.current_level)}00</td><td>${status(s.status)}</td><td><button class="btn btn-sm btn-outline-primary mb-1" data-action="edit-student" data-id="${s.id}" data-program="${s.programme_id}" data-level="${s.current_level}" data-status="${e(s.status)}">Edit</button><select class="form-select form-select-sm" data-student-status="${s.id}" style="max-width:145px"><option value="">Change status</option>${[['active','Active'],['blocked','Block access'],['suspended','Suspend'],['graduated','Graduated'],['withdrawn','Withdrawn'],['deferred','Deferred'],['archived','Archive']].map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`:empty('No student accounts','Admitted applicants will appear here after matriculation.')}</section><div id="studentImportHolder"></div>`;
}

export async function renderAcademic(){
 const [sessionData,departmentData,schoolData,programmeData,semesterData,gradingData]=await Promise.all([api('/academic/sessions'),api('/academic/departments'),api('/academic/schools'),api('/academic/programmes'),api('/academic/semesters'),api('/academic/grading-rules')]);
 const sessions=sessionData.sessions,departments=departmentData.departments,schools=schoolData.schools,programmes=programmeData.programmes,semesters=semesterData.semesters,gradingRules=gradingData.rules;
 return `<div class="row g-3"><div class="col-xl-7"><section class="panel-card">${sectionHead('Academic sessions','Choose the active session and set the registration window')}<form data-form="session" class="row g-2 align-items-end mb-4"><div class="col-md-3">${field('Session','name','text','','required placeholder="2027/2028"')}</div><div class="col-md-3">${field('Start date','startsOn','date')}</div><div class="col-md-3">${field('End date','endsOn','date')}</div><div class="col-md-3">${field('Registration opens','registrationOpensAt','datetime-local')}</div><div class="col-md-3">${field('Registration closes','registrationClosesAt','datetime-local')}</div><div class="col-md-3"><button class="btn btn-primary w-100">Add session</button></div></form>${sessions.map(s=>`<div class="d-flex align-items-center justify-content-between gap-3 py-3 border-top"><div><div class="fw-semibold">${e(s.name)} ${s.is_current?'<span class="badge-soft status-active ms-1">Current</span>':''}</div><div class="section-subtitle">${date(s.starts_on)} – ${date(s.ends_on)} · Registration closes ${date(s.registration_closes_at)}</div></div>${s.is_current?'':`<button class="btn btn-sm btn-outline-primary" data-action="set-session" data-id="${s.id}">Set current</button>`}</div>`).join('')}</section></div><div class="col-xl-5"><section class="panel-card">${sectionHead('Departments','Create departments within a school')}<form data-form="department" class="mb-4"><div class="mb-2">${selectField('School','schoolId',options(schools,'id','name'))}</div><div class="row g-2"><div class="col-7">${field('Department name','name','text','','required')}</div><div class="col-5">${field('Short code','code','text','','required')}</div></div><button class="btn btn-primary btn-sm mt-3">Add department</button></form>${departments.map(d=>`<div class="d-flex justify-content-between py-2 border-top"><span class="fw-semibold small">${e(d.name)}</span><span class="text-muted small">${e(d.school)}</span></div>`).join('')}</section></div><div class="col-12"><section class="panel-card">${sectionHead('Programmes','Manage the published ND and HND programme catalogue')}<form data-form="programme" class="row g-2 align-items-end mb-4"><div class="col-lg-3"><label class="form-label">Department</label><select class="form-select" name="departmentId">${departments.map(d=>`<option value="${d.id}">${e(d.school)} · ${e(d.name)}</option>`).join('')}</select></div><div class="col-lg-4">${field('Programme name','name','text','','required')}</div><div class="col-lg-2">${selectField('Qualification','qualification',[['ND','ND'],['HND','HND']])}</div><div class="col-lg-1">${field('Years','durationYears','number','2','min="1" max="5"')}</div><div class="col-lg-2"><button class="btn btn-primary w-100">Add programme</button></div></form>${programmes.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Programme</th><th>School</th><th>Department</th><th>Qualification</th><th>Duration</th><th>Availability</th></tr></thead><tbody>${programmes.map(p=>`<tr><td class="fw-semibold">${e(p.name)}</td><td>${e(p.school)}</td><td>${e(p.department)}</td><td>${e(p.qualification)}</td><td>${e(p.duration_years)} years</td><td><select class="form-select form-select-sm" data-program-active="${p.id}" data-program-name="${e(p.name)}" style="max-width:140px"><option value="true" ${p.is_active?'selected':''}>Active</option><option value="false" ${!p.is_active?'selected':''}>Inactive</option></select></td></tr>`).join('')}</tbody></table></div>`:empty('No programmes')}</section></div><div class="col-12"><section class="panel-card">${sectionHead('Semesters and registration windows','Select the active semester and control when students can submit course registration')}${semesters.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Session</th><th>Semester</th><th>Current</th><th>Opens</th><th>Closes</th><th>Update window</th></tr></thead><tbody>${semesters.map(s=>`<tr><td>${e(s.academic_session)}</td><td class="fw-semibold">${e(s.name)}</td><td>${s.is_current&&s.session_is_current?'<span class="badge-soft status-active">Current</span>':s.session_is_current?`<button class="btn btn-sm btn-outline-primary" data-action="set-semester" data-id="${s.id}">Set current</button>`:'—'}</td><td>${date(s.registration_opens_at)}</td><td>${date(s.registration_closes_at)}</td><td><form data-form="semester-period" class="d-flex gap-2 align-items-center"><input type="hidden" name="id" value="${s.id}"><input class="form-control form-control-sm" type="datetime-local" name="opensAt" value="${e(String(s.registration_opens_at||'').replace(' ','T').slice(0,16))}"><input class="form-control form-control-sm" type="datetime-local" name="closesAt" value="${e(String(s.registration_closes_at||'').replace(' ','T').slice(0,16))}"><button class="btn btn-sm btn-primary">Save</button></form></td></tr>`).join('')}</tbody></table></div>`:empty('No semesters defined','Create an academic session to generate its semesters.')}</section></div><div class="col-12"><section class="panel-card">${sectionHead('Grading scale','Configure score bands and grade points used when recording results')}<form data-form="grading-rule" class="row g-2 align-items-end mb-4"><div class="col-lg-2">${field('Minimum score','minimumScore','number','','required min="0" max="100" step="0.01"')}</div><div class="col-lg-2">${field('Maximum score','maximumScore','number','','required min="0" max="100" step="0.01"')}</div><div class="col-lg-2">${field('Grade','grade','text','','required maxlength="3"')}</div><div class="col-lg-2">${field('Grade point','gradePoint','number','','required min="0" max="10" step="0.01"')}</div><div class="col-lg-2">${field('Remark','remark','text','','required')}</div><div class="col-lg-2"><button class="btn btn-primary w-100">Add grade band</button></div></form>${gradingRules.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Score range</th><th>Grade</th><th>Grade point</th><th>Remark</th><th></th></tr></thead><tbody>${gradingRules.map(g=>`<tr><td>${e(g.minimum_score)}–${e(g.maximum_score)}</td><td class="fw-bold">${e(g.grade)}</td><td>${e(g.grade_point)}</td><td>${e(g.remark)}</td><td><button class="btn btn-sm btn-outline-primary" data-action="edit-grading-rule" data-id="${g.id}" data-min="${e(g.minimum_score)}" data-max="${e(g.maximum_score)}" data-grade="${e(g.grade)}" data-point="${e(g.grade_point)}" data-remark="${e(g.remark)}">Edit</button></td></tr>`).join('')}</tbody></table></div>`:empty('No grading scale configured')}</section></div></div>`;
}

export async function renderCourses(user){
 const {programmes}=await api('/academic/programmes'); const admin=user.role==='admin';
 let courses=[]; let semester=null;
 if(admin){courses=(await api('/academic/courses')).courses;}else{const results=await Promise.all([api('/academic/courses'),api('/academic/semester/current')]);courses=results[0].courses;semester=results[1].semester;if(semester)courses=courses.filter(c=>c.semester===semester.name);}
 const registrations=user.role==='student'?(await api('/academic/registration')).registrations:[];
 const registered=new Set(registrations.map(r=>Number(r.course_id)));
 return admin?`<div class="row g-3"><div class="col-xl-4"><form data-form="course" class="panel-card"><h3 class="section-title mb-3">Add a course</h3><div class="mb-3">${selectField('Programme','programmeId',options(programmes,'id','name').map(([id,name])=>{const p=programmes.find(x=>String(x.id)===String(id));return[id,`${p.qualification} · ${name}`]}))}</div><div class="mb-3">${field('Course code','code','text','','required')}</div><div class="mb-3">${field('Course title','title','text','','required')}</div><div class="row g-2 mb-3"><div class="col-6">${field('Credit units','creditUnits','number','','required min="1" max="10"')}</div><div class="col-6">${field('Level','level','number','','required min="1" max="5"')}</div></div><div class="mb-3">${selectField('Semester','semester',[['First Semester','First Semester'],['Second Semester','Second Semester']])}</div><button class="btn btn-primary w-100">Create course</button></form></div><div class="col-xl-8"><section class="panel-card">${sectionHead('Course catalogue','Programmes, course units and semester assignments')}${courses.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Code</th><th>Course title</th><th>Programme</th><th>Level</th><th>Semester</th><th>Units</th></tr></thead><tbody>${courses.map(c=>`<tr><td class="fw-semibold">${e(c.code)}</td><td>${e(c.title)}</td><td>${e(c.programme)}</td><td>${e(c.level)}00</td><td>${e(c.semester)}</td><td>${e(c.credit_units)}</td></tr>`).join('')}</tbody></table></div>`:empty('No courses created','Create the programme course catalogue from the form.')}</section></div></div>`:
 `<div class="row g-3"><div class="col-xl-8"><section class="panel-card">${sectionHead('Course registration',semester?`${semester.academic_session} · ${semester.name}`:'No current semester configured',`<button class="btn btn-primary btn-sm" data-action="print-registration"><i class="bi bi-printer me-1"></i>Print slip</button>`)}${semester&&new Date(semester.registration_closes_at)<new Date()?'<div class="lock-note mb-3">Course registration has closed for this semester.</div>':''}${courses.length?`<form data-form="registration"><div class="d-flex justify-content-between small text-muted mb-2"><span>Select your semester courses</span><span id="unitTotal">Selected units: 0</span></div>${courses.map(c=>`<label class="course-row"><input class="form-check-input course-choice" type="checkbox" name="courseIds" value="${c.id}" data-units="${c.credit_units}" ${registered.has(Number(c.id))?'checked disabled':''}><span><span class="course-code">${e(c.code)} ${registered.has(Number(c.id))?'<span class="badge-soft status-submitted ms-1">registered</span>':''}</span><span class="course-title d-block">${e(c.title)}</span></span><span class="course-units">${c.credit_units} units</span></label>`).join('')}<div class="d-flex justify-content-end mt-3"><button class="btn btn-primary" ${!semester?'disabled':''}>Submit registration</button></div></form>`:empty('Course list unavailable','Your department has not added courses for this level and semester.')}</section></div><div class="col-xl-4"><section class="panel-card">${sectionHead('Registration history','Submitted semester records')}${registrations.length?registrations.map(r=>`<div class="d-flex align-items-center justify-content-between border-top py-3 gap-2"><div><div class="fw-semibold small">${e(r.code)} · ${e(r.title)}</div><div class="section-subtitle">${e(r.academic_session)} · ${e(r.semester)}</div></div>${status(r.status)}</div>`).join(''):empty('No registrations yet')}</section></div></div>`;
}

export async function renderRegistrations(){
 const {registrations}=await api('/academic/registration');
 return `<section class="panel-card">${sectionHead('Course registrations','Review student course loads and approve or reopen submissions')}<div class="toolbar mb-3"><input class="form-control form-control-sm" id="registrationSearch" placeholder="Search student or course"><span class="chip"><i class="bi bi-journal-check"></i>${registrations.length} registered courses</span></div>${registrations.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Session and semester</th><th>Course</th><th>Units</th><th>Status</th><th>Registered</th><th></th></tr></thead><tbody>${registrations.map(r=>`<tr data-search-row="${e(`${r.first_name} ${r.last_name} ${r.matriculation_number} ${r.code} ${r.title}`.toLowerCase())}"><td><div class="fw-semibold">${e(r.first_name)} ${e(r.last_name)}</div><div class="text-muted small">${e(r.matriculation_number)}</div></td><td>${e(r.academic_session)}<div class="text-muted small">${e(r.semester)}</div></td><td><div class="fw-semibold">${e(r.code)}</div><div class="text-muted small">${e(r.title)}</div></td><td>${e(r.credit_units)}</td><td>${status(r.status)}</td><td>${date(r.registered_at)}</td><td>${r.status==='submitted'||r.status==='reopened'?`<button class="btn btn-sm btn-primary" data-action="registration-status" data-id="${r.id}" data-status="approved">Approve</button>`:`<button class="btn btn-sm btn-outline-secondary" data-action="registration-status" data-id="${r.id}" data-status="reopened">Reopen</button>`}</td></tr>`).join('')}</tbody></table></div>`:empty('No registrations yet')}</section>`;
}

export async function renderResults(user){
 const resultsPayload=await api('/academic/results');const results=resultsPayload.results;
 if(user.role==='admin'){
  const {students}=await api('/students');const {courses}=await api('/academic/courses');const {sessions}=await api('/academic/sessions');
  const semesters=(await api('/academic/semesters')).semesters;
  return `<div class="row g-3"><div class="col-xl-4"><form data-form="result" class="panel-card"><h3 class="section-title mb-3">Enter or update a result</h3><div class="mb-3">${selectField('Student','studentId',students.map(s=>[s.id,`${s.matriculation_number} · ${s.first_name} ${s.last_name}`]))}</div><div class="mb-3">${selectField('Course','courseId',courses.map(c=>[c.id,`${c.code} · ${c.title}`]))}</div><div class="mb-3">${selectField('Semester','semesterId',semesters.map(s=>[s.id,`${s.academic_session} · ${s.name}`]))}</div><div class="row g-2"><div class="col-6">${field('Continuous assessment','caScore','number','','required min="0" max="100" step="0.01"')}</div><div class="col-6">${field('Examination','examScore','number','','required min="0" max="100" step="0.01"')}</div></div><button class="btn btn-primary w-100 mt-3">Save result</button><div class="input-hint mt-2">Grading follows the grade bands set in the database.</div></form><form data-form="results-import" class="panel-card mt-3"><h3 class="section-title">Bulk CSV upload</h3><p class="section-subtitle">Required headers: student_id, course_id, semester_id, ca_score, exam_score</p><input class="form-control mt-3" name="file" type="file" accept=".csv" required><button class="btn btn-outline-primary btn-sm mt-3">Import CSV results</button></form></div><div class="col-xl-8"><section class="panel-card">${sectionHead('Results register','Review marks and publish results to student accounts')}${resultTable(results,true)}</section></div></div>`;
 }
 const weighted=results.reduce((acc,r)=>{acc.points+=Number(r.grade_point||0)*Number(r.credit_units||0);acc.units+=Number(r.credit_units||0);return acc;},{points:0,units:0});const gpa=weighted.units?(weighted.points/weighted.units).toFixed(2):'—';
 const semesterSummary=resultsPayload.semesterGpas||[];
 return `<div class="row g-3 mb-3">${metric('Published courses',results.length,'bi-journal-check','blue','Courses with published results')}${metric('Current CGPA',gpa,'bi-bar-chart-line','gold','Average of published course grade points')}${metric('Academic status',results.some(r=>r.grade==='F')?'Review required':'In good standing','bi-award','green','Based on published marks')}${metric('Academic session',results[0]?.academic_session||'—','bi-calendar3','red','Latest published session')}</div><section class="panel-card">${sectionHead('Academic results','Only results published by the Academic Office appear here',`<button class="btn btn-sm btn-outline-primary" data-action="print-results"><i class="bi bi-printer me-1"></i>Print result slip</button>`)}${semesterSummary.length?`<div class="table-wrap mb-3"><table class="table"><thead><tr><th>Session</th><th>Semester</th><th>Credit units</th><th>Semester GPA</th></tr></thead><tbody>${semesterSummary.map(x=>`<tr><td>${e(x.academic_session)}</td><td>${e(x.semester)}</td><td>${e(x.credit_units)}</td><td class="fw-bold">${Number(x.gpa).toFixed(2)}</td></tr>`).join('')}</tbody></table></div>`:''}${resultTable(results,false)}</section><div class="row g-3 mt-1"><div class="col-xl-7"><section class="panel-card">${sectionHead('Performance by course','Published grade points')}<div class="chart-box"><canvas id="resultsChart"></canvas></div></section></div><div class="col-xl-5"><div class="lock-note">Questions about a score? Open a support ticket with the course code and semester. Result corrections are reviewed by the Academic Office.</div><a class="btn btn-outline-primary mt-3" href="#support" data-page="support">Contact Student Services</a></div></div>`;
}
function resultTable(rows,admin){return rows.length?`<div class="table-wrap"><table class="table"><thead><tr>${admin?'<th>Student</th>':''}<th>Session</th><th>Semester</th><th>Course</th><th>CA</th><th>Exam</th><th>Total</th><th>Grade</th><th>GP</th>${admin?'<th>Visibility</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr>${admin?`<td><div class="fw-semibold">${e(r.first_name)} ${e(r.last_name)}</div><div class="text-muted small">${e(r.matriculation_number)}</div>`:''}<td>${e(r.academic_session)}</td><td>${e(r.semester)}</td><td><div class="fw-semibold">${e(r.code)}</div><div class="text-muted small">${e(r.title)}</div></td><td>${e(r.ca_score)}</td><td>${e(r.exam_score)}</td><td class="score">${e(r.total_score)}</td><td class="fw-bold">${e(r.grade||'—')}</td><td>${e(r.grade_point??'—')}</td>${admin?`<td><button class="btn btn-sm ${r.published?'btn-outline-secondary':'btn-primary'}" data-action="publish-result" data-id="${r.id}">${r.published?'Unpublish':'Publish'}</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:empty('No published results','Your published result slip will appear here.');}

export async function renderCalendar(user){const {events}=await api('/academic/calendar');const sessions=user.role==='admin'?(await api('/academic/sessions')).sessions:[];return `<div class="row g-3"><div class="${user.role==='admin'?'col-xl-8':'col-12'}"><section class="panel-card">${sectionHead('Academic calendar','Important dates for your academic session')}${events.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Activity</th><th>Session</th><th>Starts</th><th>Ends</th><th>Details</th></tr></thead><tbody>${events.map(x=>`<tr><td class="fw-semibold">${e(x.title)}</td><td>${e(x.academic_session)}</td><td>${date(x.starts_at,{month:'short',day:'numeric',year:'numeric'})}</td><td>${date(x.ends_at)}</td><td>${e(x.description||'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('No calendar events','Dates will be added by the Academic Office.')}</section></div>${user.role==='admin'?`<div class="col-xl-4"><form data-form="calendar" class="panel-card"><h3 class="section-title mb-3">Add an event</h3><div class="mb-3">${selectField('Academic session','sessionId',sessions.map(s=>[s.id,s.name]))}</div><div class="mb-3">${field('Event title','title','text','','required')}</div><div class="mb-3">${field('Starts','startsAt','datetime-local','','required')}</div><div class="mb-3">${field('Ends','endsAt','datetime-local')}</div><div class="mb-3"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="3"></textarea></div><button class="btn btn-primary w-100">Add calendar event</button></form></div>`:''}</div>`;}

export async function renderAnnouncements(user){const {announcements}=await api('/announcements');return user.role==='admin'?`<div class="row g-3"><div class="col-xl-4"><form data-form="announcement" class="panel-card"><h3 class="section-title mb-3">Publish an announcement</h3><div class="mb-3">${field('Title','title','text','','required')}</div><div class="mb-3"><label class="form-label">Message</label><textarea class="form-control" name="body" rows="6" required></textarea></div><div class="row g-2 mb-3"><div class="col-7">${selectField('Audience','audience',[['students','Students'],['applicants','Applicants'],['all','Everyone'],['staff','Staff']])}</div><div class="col-5">${selectField('Priority','priority',[['normal','Normal'],['important','Important'],['urgent','Urgent']])}</div></div><button class="btn btn-primary w-100"><i class="bi bi-megaphone me-1"></i>Publish announcement</button></form></div><div class="col-xl-8"><section class="panel-card">${sectionHead('Announcement archive','Published and scheduled notices')} ${announcementTable(announcements,true)}</section></div></div>`:`<section class="panel-card">${sectionHead('Announcements','Updates from Lens Polytechnic')} ${announcementTable(announcements,false)}</section>`;}
function announcementTable(rows,admin){return rows.length?rows.map(a=>`<div class="announcement-item"><div class="d-flex align-items-start justify-content-between gap-3"><div><div class="announcement-title">${e(a.title)}</div><div class="announcement-body">${e(a.body)}</div><div class="announcement-meta">${date(a.created_at)} · ${e(a.audience||'students')}</div></div><div class="text-end"><span class="priority priority-${e(a.priority)}">${e(a.priority)}</span>${admin?`<div class="mt-2"><button class="btn btn-sm btn-outline-danger" data-action="delete-announcement" data-id="${a.id}"><i class="bi bi-trash"></i></button></div>`:''}</div></div></div>`).join(''):empty('No announcements');}

export async function renderMessages(user){const {messages}=await api('/messages');let students=[];if(user.role==='admin')students=(await api('/students')).students;return `<div class="row g-3"><div class="col-xl-4"><form data-form="message" class="panel-card"><h3 class="section-title mb-3">${user.role==='admin'?'Send a student message':'Message Student Services'}</h3>${user.role==='admin'?`<div class="mb-3">${selectField('Student','recipientUserId',students.map(s=>[s.user_id,`${s.matriculation_number} · ${s.first_name} ${s.last_name}`]))}</div>`:''}<div class="mb-3">${field('Subject','subject','text','','required')}</div><div class="mb-3"><label class="form-label">Message</label><textarea class="form-control" name="body" rows="6" required></textarea></div><button class="btn btn-primary w-100"><i class="bi bi-send me-1"></i>Send message</button></form></div><div class="col-xl-8"><section class="panel-card">${sectionHead('Inbox and sent messages','Your portal conversation history')} ${messages.length?messages.map(m=>`<div class="announcement-item"><div class="d-flex justify-content-between gap-3"><div class="announcement-title">${e(m.subject)}</div><div class="announcement-meta">${date(m.created_at,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</div></div><div class="announcement-meta">From ${e(m.sender_first)} ${e(m.sender_last)} · To ${e(m.recipient_first)} ${e(m.recipient_last)}</div><div class="announcement-body">${e(m.body)}</div>${m.recipient_user_id===user.id&&!m.read_at?`<button class="btn btn-sm btn-link px-0" data-action="read-message" data-id="${m.id}">Mark as read</button>`:''}</div>`).join(''):empty('No messages yet')}</section></div></div>`;}

export async function renderSupport(user){const {tickets}=await api('/tickets');return `<div class="row g-3"><div class="col-xl-4"><form data-form="ticket" class="panel-card"><h3 class="section-title mb-3">Open a support ticket</h3><div class="mb-3">${field('Subject','subject','text','','required minlength="4"')}</div><div class="mb-3">${selectField('Category','category',[['General','General'],['Admissions','Admissions'],['Registration','Course registration'],['Results','Results'],['Documents','Documents'],['Fees','Fees'],['Technical','Technical support']])}</div><div class="mb-3"><label class="form-label">Describe the issue</label><textarea class="form-control" name="body" rows="5" required minlength="5"></textarea></div><button class="btn btn-primary w-100">Submit ticket</button></form></div><div class="col-xl-8"><section class="panel-card">${sectionHead(user.role==='admin'?'Support queue':'My support tickets','Messages and follow-up for portal issues')}${tickets.length?`<div class="table-wrap"><table class="table"><thead><tr>${user.role==='admin'?'<th>Student</th>':''}<th>Ticket</th><th>Subject</th><th>Priority</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody>${tickets.map(t=>`<tr>${user.role==='admin'?`<td>${e(t.first_name)} ${e(t.last_name)}</td>`:''}<td>${e(t.ticket_number)}</td><td class="fw-semibold">${e(t.subject)}</td><td>${e(t.priority)}</td><td>${status(t.status)}</td><td>${date(t.updated_at)}</td><td><button class="btn btn-sm btn-outline-primary" data-action="open-ticket" data-id="${t.id}">Open</button>${user.role==='admin'?`<select class="form-select form-select-sm mt-1" data-ticket-status="${t.id}"><option value="">Update status</option>${['open','in_progress','resolved','closed'].map(x=>`<option value="${x}">${x.replace('_',' ')}</option>`).join('')}</select>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('No support tickets')}</section></div></div>`;}

export async function renderFees(user){
 const {fees}=await api('/fees');let students=[],sessions=[];
 if(user.role==='admin'){[students,sessions]=await Promise.all([api('/students'),api('/academic/sessions')]).then(([a,b])=>[a.students,b.sessions]);}
 const table=fees.length?`<div class="table-wrap"><table class="table"><thead><tr>${user.role==='admin'?'<th>Student</th>':''}<th>Fee description</th><th>Session</th><th>Amount</th><th>Paid</th><th>Balance</th><th>Status</th>${user.role==='admin'?'<th></th>':''}</tr></thead><tbody>${fees.map(f=>`<tr>${user.role==='admin'?`<td>${e(f.first_name)} ${e(f.last_name)}<div class="text-muted small">${e(f.matriculation_number)}</div></td>`:''}<td class="fw-semibold">${e(f.description)}</td><td>${e(f.academic_session)}</td><td>${money(f.amount)}</td><td>${money(f.amount_paid)}</td><td>${money(Number(f.amount)-Number(f.amount_paid))}</td><td>${status(f.status)}</td>${user.role==='admin'?`<td><button class="btn btn-sm btn-outline-primary" data-action="record-payment" data-id="${f.id}" data-balance="${Number(f.amount)-Number(f.amount_paid)}" data-label="${e(f.description)}">Record payment</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:empty('No fee accounts on record','Fee balances appear when an authorized administrator creates an account.');
 return user.role==='admin'?`<div class="row g-3"><div class="col-xl-4"><form data-form="fee" class="panel-card"><h3 class="section-title mb-3">Create fee account</h3><div class="mb-3">${selectField('Student','studentId',students.map(s=>[s.id,`${s.matriculation_number} · ${s.first_name} ${s.last_name}`]))}</div><div class="mb-3">${selectField('Academic session','sessionId',sessions.map(s=>[s.id,s.name]))}</div><div class="mb-3">${field('Description','description','text','','required')}</div><div class="mb-3">${field('Amount (₦)','amount','number','','required min="0.01" step="0.01"')}</div><div class="mb-3">${field('Due date','dueDate','date')}</div><button class="btn btn-primary w-100">Create fee account</button></form></div><div class="col-xl-8"><section class="panel-card">${sectionHead('Fee accounts','Record reconciled payments and track outstanding balances')}${table}</section></div></div>`:`<section class="panel-card">${sectionHead('My fee account','Recorded student account balances')}${table}</section>`;
}

export async function renderAdministrators(){const {users}=await api('/admin/users');return `<div class="row g-3"><div class="col-xl-4"><form data-form="admin-user" class="panel-card"><h3 class="section-title mb-3">Add administrator</h3><div class="mb-3">${field('First name','firstName','text','','required')}</div><div class="mb-3">${field('Last name','lastName','text','','required')}</div><div class="mb-3">${field('Email address','email','email','','required')}</div><div class="mb-3">${field('Temporary password','password','password','','required minlength="12"')}</div><button class="btn btn-primary w-100">Create administrator</button></form></div><div class="col-xl-8"><section class="panel-card">${sectionHead('Administrator accounts','Role-based access to the portal')}<div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Status</th><th>Last login</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td class="fw-semibold">${e(u.first_name)} ${e(u.last_name)}</td><td>${e(u.email)}</td><td>${status(u.status)}</td><td>${date(u.last_login_at)}</td><td>${u.status==='active'?`<button class="btn btn-sm btn-outline-danger" data-action="admin-status" data-id="${u.id}" data-status="blocked">Block</button>`:`<button class="btn btn-sm btn-outline-success" data-action="admin-status" data-id="${u.id}" data-status="active">Restore</button>`}</td></tr>`).join('')}</tbody></table></div></section></div></div>`;}

export async function renderReports(){const r=await api('/reports/dashboard');return `<div class="row g-3 mb-3">${metric('Active students',r.totals.active_students,'bi-people','blue','Active matriculated accounts')}${metric('Applications',r.totals.applications,'bi-person-lines-fill','gold','All application records')}${metric('Pending applications',r.totals.pending_applications,'bi-hourglass-split','red','Submitted and under review')}${metric('Published results',r.totals.published_results,'bi-journal-check','green','Published course result records')}</div><div class="row g-3"><div class="col-xl-7"><section class="panel-card">${sectionHead('Admissions trend','Applications created over the last 12 months')}<div class="chart-box"><canvas id="applicationChart"></canvas></div></section></div><div class="col-xl-5"><section class="panel-card">${sectionHead('Programme enrolment','Current student count by programme')}<div class="chart-box"><canvas id="programmeChart"></canvas></div></section></div><div class="col-12"><section class="panel-card">${sectionHead('Student records','Download the current student directory',`<div class="d-flex gap-2 flex-wrap"><button class="btn btn-sm btn-outline-primary" data-action="export-students"><i class="bi bi-download me-1"></i>Students CSV</button><button class="btn btn-sm btn-outline-primary" data-action="export-admissions">Admissions CSV</button><button class="btn btn-sm btn-outline-primary" data-action="export-registrations">Registrations CSV</button></div>`)}<div class="section-subtitle">Exports provide student, admissions and course-registration records.</div></section></div></div>`;}

export async function renderStudentCard(user){const d=await api('/dashboard');const s=d.student||{};return `<section class="panel-card"><div class="toolbar mb-4">${sectionHead('Student identity card','Print a portal identity card for your records')}<button class="btn btn-primary no-print" data-action="print-card"><i class="bi bi-printer me-1"></i>Print card</button></div>${s.matriculation_number?`<div class="id-card"><div class="id-card-top"><span class="brand-mark">L</span><span>LENS POLYTECHNIC OFFA<br><span class="fw-normal" style="font-size:9px;opacity:.8">STUDENT IDENTITY CARD</span></span></div><div class="id-card-main"><img src="/api/me/photo" alt="Passport photo"><div><div class="id-card-name">${e([s.first_name,s.middle_name,s.last_name].filter(Boolean).join(' '))}</div><div class="id-card-data">MAT NO · ${e(s.matriculation_number)}<br>PROGRAMME · ${e(s.qualification)} ${e(s.programme)}<br>DEPARTMENT · ${e(s.department)}<br>LEVEL · ${e(s.current_level)}00</div></div></div><div class="id-card-foot"><span>KM2 Irra Road, Offa · Kwara State</span><span>${e(d.session?.name||'Lens Polytechnic')}</span></div></div>`:empty('Your identity card is not ready','A student card is available after your admission is approved and matriculation number is assigned.')}</section>`;}

export function renderSettings(){return `<div class="row g-3"><div class="col-lg-7"><form data-form="password-change" class="panel-card"><h3 class="section-title mb-1">Change password</h3><p class="section-subtitle mb-4">Use at least 10 characters. You will be signed out after changing your password.</p><div class="mb-3">${field('Current password','currentPassword','password','','required')}</div><div class="mb-3">${field('New password','newPassword','password','','required minlength="10"')}</div><div class="mb-3">${field('Confirm new password','confirmPassword','password','','required minlength="10"')}</div><button class="btn btn-primary">Update password</button></form></div><div class="col-lg-5"><section class="panel-card">${sectionHead('Account security')}<div class="announcement-body">Your account is protected with a secure session. Sign out when using a shared device. Contact an administrator if you think your account has been used by someone else.</div><button class="btn btn-outline-danger mt-3" data-action="logout">Sign out of this device</button></section></div></div>`;}

export async function renderNotifications(){const {notifications}=await api('/notifications');return `<section class="panel-card">${sectionHead('Notifications','Application and account activity',`<button class="btn btn-sm btn-outline-primary" data-action="read-all">Mark all as read</button>`)}${notifications.length?notifications.map(n=>`<div class="announcement-item ${n.read_at?'':'bg-light rounded-3 px-3'}"><div class="d-flex justify-content-between gap-2"><div class="announcement-title">${e(n.title)} ${n.read_at?'':'<span class="badge-soft status-submitted ms-1">New</span>'}</div><span class="announcement-meta">${date(n.created_at)}</span></div><div class="announcement-body">${e(n.body)}</div>${n.link?`<a class="small" href="#${e(n.link.split('/').pop())}" data-page="${e(n.link.split('/').pop())}">Open related page <i class="bi bi-arrow-right"></i></a>`:''}</div>`).join(''):empty('You are all caught up')}</section>`;}

export async function initCharts(page,user){
 if(typeof Chart==='undefined')return;
 const make=(id,type,labels,data,color='#245b91')=>{const canvas=document.getElementById(id);if(!canvas)return;new Chart(canvas,{type,data:{labels,datasets:[{label:'Students',data,backgroundColor:type==='bar'?color:['#245b91','#d6a642','#39a176','#8d78b4','#db7869','#5baeb2'],borderRadius:type==='bar'?6:undefined,borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:type==='doughnut',position:'bottom',labels:{boxWidth:9,usePointStyle:true,font:{size:10}}}},scales:type==='bar'?{y:{beginAtZero:true,ticks:{precision:0},grid:{color:'#edf1f5'}},x:{grid:{display:false}}}:{}}});};
 if(page==='dashboard'&&user.role==='admin'||page==='reports'){const d=await api('/reports/dashboard');make('applicationChart','bar',d.applicationsByMonth.map(x=>x.month),d.applicationsByMonth.map(x=>x.count));make('programmeChart','doughnut',d.byProgramme.map(x=>`${x.qualification} ${x.name}`),d.byProgramme.map(x=>x.students));}
 if(page==='results'&&user.role==='student'){const {results}=await api('/academic/results');make('resultsChart','bar',results.map(r=>r.code),results.map(r=>Number(r.grade_point||0)),'#d6a642');}
}
